mapper.select:
SELECT COUNT(*) FROM OPS_CODE WHERE 1 = 1
AND CODE_GRP = #{searchCondition}
AND (CODE_ID LIKE '%' || #{searchKeyword} || '%' OR CODE_NM LIKE '%' || #{searchKeyword} || '%')

mapper.update:
UPDATE OPS_CODE
   SET CODE_NM = #{codeNm}, SORT_ORDR = #{sortOrdr}, USE_AT = #{useAt},
       UPPER_CODE = #{upperCode}
 WHERE CODE_GRP = #{codeGrp} AND CODE_ID = #{codeId}
